using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PowderTransportOperations
{
    private static Settings Inventory(int count,float[] masses,byte[] phase){var result=new Settings{["active"]=0.0,["deposited"]=0.0,["airborne"]=0.0,["total"]=0.0,["count"]=count};var names=new[]{"active","deposited","airborne"};for(int i=0;i<count;i++){double mass=masses[i];result["total"]=result["total"].AsDouble()+mass;string key=names[phase[i]];result[key]=result[key].AsDouble()+mass;}return result;}
    public Settings inventory(Settings state)=>Inventory(state["points"].AsVector3Array().Length,state["powder_masses"].AsFloat32Array(),state["powder_phase"].AsByteArray());
    public void after(RefCounted controller,GArray batches,double time)
    {
        foreach(var value in batches){var batch=value.AsGodotDictionary();if(!batch["moving"].AsBool())continue;var state=new State(batch["state"].AsGodotDictionary());var s=batch["settings"].AsGodotDictionary();var cells=new Settings();var supports=Get(state.Data,"powder_supports",new Settings()).AsGodotDictionary();var gravity=batch["gravity"].AsVector3();for(int i=0;i<state.Points.Length;i++){if(state.Phase[i]==1)continue;var support=supports.TryGetValue(state.Ids[i],out var entry)?entry.AsGodotDictionary():new Settings();double speed=state.Velocities[i].Length();state.Phase[i]=(byte)(Get(s,"powder_airborne",true).AsBool()&&support.Count==0&&speed>Get(s,"powder_airborne_threshold",.2).AsDouble()?2:0);if(!Get(s,"powder_deposition",false).AsBool()||support.Count==0){state.Settle[i]=0;continue;}string owner=Get(support,"actor","").AsString();var other=Get(Map(controller,"states"),owner,new Settings()).AsGodotDictionary();if(other.Count==0||!other["active"].AsBool())continue;var config=Config(controller,owner,time);if(!config["powder_accumulation"].AsBool())continue;var normal=support["normal"].AsVector3();var relative=state.Velocities[i]-Get(support,"velocity",Vector3.Zero).AsVector3();double supportForce=Math.Max(0,normal.Dot((-gravity).Normalized())),adhesion=Get(s,"powder_adhesion",0).AsDouble()+config["powder_adhesion"].AsDouble();if(supportForce<.2&&adhesion<state.Masses[i]*gravity.Length())continue;if(relative.Length()>Get(s,"powder_settling",.08).AsDouble()){state.Settle[i]=0;continue;}state.Settle[i]+=batch["h"].AsSingle();if(state.Settle[i]<s["sleep_delay"].AsDouble())continue;var pose=other["pose"].AsTransform3D();var local=pose.AffineInverse()*state.Points[i];double radius=state.Radii[i];if(radius*2>Math.Min(Get(s,"powder_coating",.25).AsDouble(),config["powder_max_coating"].AsDouble()))continue;string proxy=Get(support,"proxy","").AsString();int index=ProxyIndex(proxy);var otherPoints=other["points"].AsVector3Array();var offset=index>=0&&index<otherPoints.Length?state.Points[i]-otherPoints[index]:Vector3.Zero;var deposit=new Settings{["actor"]=owner,["proxy"]=proxy,["local"]=local,["normal"]=pose.Basis.Transposed()*normal,["proxy_offset"]=offset,["damage"]=0.0};state.Deposits[state.Ids[i]]=deposit;var bodies=ProxyBodies(controller);if(bodies.ContainsKey(proxy)){var proxyPose=PhysicsServer3D.BodyGetState(bodies[proxy].AsGodotDictionary()["rid"].AsRid(),PhysicsServer3D.BodyState.Transform).AsTransform3D();deposit["proxy_local"]=proxyPose.AffineInverse()*state.Points[i];deposit["proxy_normal"]=proxyPose.Basis.Inverse()*normal;}state.Phase[i]=1;state.Velocities[i]=Get(support,"velocity",Vector3.Zero).AsVector3();}
            for(int i=0;i<state.Points.Length;i++){if(state.Phase[i]!=1)continue;var deposit=state.Deposits[state.Ids[i]].AsGodotDictionary();double radius=state.Radii[i];var coordinate=(deposit["local"].AsVector3()/(float)Math.Max(.001,radius*4)).Floor();var cell=new Vector3I((int)coordinate.X,(int)coordinate.Y,(int)coordinate.Z);string key=deposit["actor"].AsString()+":"+Variant.From(cell).ToString();if(!cells.ContainsKey(key))cells[key]=new Settings{["actor"]=deposit["actor"],["mass"]=0.0,["volume"]=0.0,["area"]=Math.Max(.000001,radius*radius*16),["count"]=0};var record=cells[key].AsGodotDictionary();record["mass"]=record["mass"].AsDouble()+state.Masses[i];record["volume"]=record["volume"].AsDouble()+4.0/3*Math.PI*Math.Pow(radius,3);record["count"]=record["count"].AsInt64()+1;record["thickness"]=record["volume"].AsDouble()/record["area"].AsDouble();}state.Data["powder_cells"]=cells;state.Data["powder_inventory"]=Inventory(state.Points.Length,state.Masses,state.Phase);state.Commit();
        }
    }
}
